public class TrendStack {
    private static class Node {
        int value;
        int frequency;  // frequency of this value in the stack
    }

    private final Stack<Integer> stack;
    private final Map<Integer, Integer> frequencyMap;  // value -> frequency
    private final TreeMap<Integer, Integer> modeTracker;  // frequency -> count of values with that frequency
    private int currentMode;  // the most frequent value

    public TrendStack() {
        this.stack = new Stack<>();
        this.frequencyMap = new HashMap<>();
        this.modeTracker = new TreeMap<>(Collections.reverseOrder());
        this.currentMode = Integer.MIN_VALUE;
    }

    public void push(int value) {
        stack.push(value);

        // Update old frequency
        int oldFreq = frequencyMap.getOrDefault(value, 0);
        if (oldFreq > 0) {
            int countAtOldFreq = modeTracker.get(oldFreq);
            if (countAtOldFreq == 1) {
                modeTracker.remove(oldFreq);
            } else {
                modeTracker.put(oldFreq, countAtOldFreq - 1);
            }
        }

        // Update new frequency
        int newFreq = oldFreq + 1;
        frequencyMap.put(value, newFreq);
        modeTracker.put(newFreq, modeTracker.getOrDefault(newFreq, 0) + 1);

        // Update current mode (highest frequency)
        currentMode = modeTracker.firstEntry().getKey() > 0 ? value : currentMode;
    }

    public int pop() {
        if (stack.isEmpty()) {
            throw new EmptyStackException();
        }

        int value = stack.pop();

        // Update frequency tracking
        int oldFreq = frequencyMap.get(value);
        int countAtOldFreq = modeTracker.get(oldFreq);

        if (countAtOldFreq == 1) {
            modeTracker.remove(oldFreq);
        } else {
            modeTracker.put(oldFreq, countAtOldFreq - 1);
        }

        // Update to new frequency
        int newFreq = oldFreq - 1;
        if (newFreq == 0) {
            frequencyMap.remove(value);
        } else {
            frequencyMap.put(value, newFreq);
            modeTracker.put(newFreq, modeTracker.getOrDefault(newFreq, 0) + 1);
        }

        // Recalculate mode if necessary
        if (modeTracker.isEmpty()) {
            currentMode = Integer.MIN_VALUE;
        }

        return value;
    }

    /**
     * Returns the most frequent value currently in the stack.
     * Ties broken arbitrarily (last mode seen wins).
     * O(1) amortized.
     */
    public int getMode() {
        if (stack.isEmpty()) {
            throw new EmptyStackException();
        }
        return currentMode;
    }
}
```

