public class MinimaxStack {
    private static class Node {
        int value;
        int minBelow;
        int maxBelow;

        Node(int value, int minBelow, int maxBelow) {
            this.value = value;
            this.minBelow = minBelow;
            this.maxBelow = maxBelow;
        }
    }

    private ArrayList<Node> stack;

    public MinimaxStack() {
        stack = new ArrayList<>();
    }

    public void push(int value) {
        int newMin = stack.isEmpty() ? value : Math.min(value, stack.get(stack.size() - 1).minBelow);
        int newMax = stack.isEmpty() ? value : Math.max(value, stack.get(stack.size() - 1).maxBelow);
        stack.add(new Node(value, newMin, newMax));
    }

    public int pop() {
        if (stack.isEmpty()) throw new EmptyStackException();
        return stack.remove(stack.size() - 1).value;
    }

    public int getSpan() {
        if (stack.isEmpty()) throw new EmptyStackException();
        Node top = stack.get(stack.size() - 1);
        return top.maxBelow - top.minBelow;
    }

    public static void main(String[] args) {
        MinimaxStack s = new MinimaxStack();
        s.push(5); s.push(2); s.push(8); s.push(1);
        System.out.println(s.getSpan()); // 8-1 = 7
        s.pop();
        System.out.println(s.getSpan()); // 8-2 = 6
    }
}
```

